<script setup lang="ts">
import { reactive } from 'vue'; import { useRouter } from 'vue-router'; import AuthLayout from '@/components/AuthLayout.vue'; import AvatarUploader from '@/components/AvatarUploader.vue'; import BaseInput from '@/components/BaseInput.vue'; import BaseSelect from '@/components/BaseSelect.vue'; import FormAlert from '@/components/FormAlert.vue'; import PasswordInput from '@/components/PasswordInput.vue'; import PrimaryButton from '@/components/PrimaryButton.vue'; import RoleSelector from '@/components/RoleSelector.vue'; import { homeForRole, useAuthStore } from '@/stores/auth'; import type { RegisterPayload } from '@/types/auth'
const auth = useAuthStore(); const router = useRouter(); const form = reactive<RegisterPayload>({ name: '', email: '', gender: 'prefer_not_to_say', birth_date: '', password: '', password_confirmation: '', role: 'user', company_name: '', avatar: null }); const genders = [{ value: 'prefer_not_to_say', label: 'Prefiero no decirlo' }, { value: 'female', label: 'Femenino' }, { value: 'male', label: 'Masculino' }, { value: 'non_binary', label: 'No binario' }]
function error(field: string) { return auth.errors[field]?.[0] }
async function submit() { try { await auth.register(form); if (auth.user) await router.push(homeForRole(auth.user.role)) } catch { form.password = ''; form.password_confirmation = '' } }
</script>
<template><AuthLayout><h1>Crea tu cuenta</h1><p class="form-intro">Completa tu perfil y elige cómo usarás AppNova.</p><form @submit.prevent="submit"><FormAlert :message="auth.message" /><AvatarUploader :error="error('avatar')" :disabled="auth.loading" @update:model-value="form.avatar = $event" /><BaseInput id="name" v-model="form.name" label="Nombre completo" autocomplete="name" required :error="error('name')" :disabled="auth.loading" /><div class="field-grid"><BaseSelect id="gender" v-model="form.gender" label="Género" :options="genders" required :error="error('gender')" :disabled="auth.loading" /><BaseInput id="birth_date" v-model="form.birth_date" label="Fecha de nacimiento" type="date" autocomplete="bday" required :error="error('birth_date')" :disabled="auth.loading" /></div><BaseInput id="email" v-model="form.email" label="Correo electrónico" type="email" autocomplete="email" required :error="error('email')" :disabled="auth.loading" /><div class="field-grid"><PasswordInput id="password" v-model="form.password" label="Contraseña" autocomplete="new-password" required :error="error('password')" :disabled="auth.loading" /><PasswordInput id="password_confirmation" v-model="form.password_confirmation" label="Confirmar contraseña" autocomplete="new-password" required :disabled="auth.loading" /></div><RoleSelector v-model="form.role" :error="error('role')" :disabled="auth.loading" /><BaseInput v-if="form.role === 'developer'" id="company_name" v-model="form.company_name" label="Empresa" autocomplete="organization" required :error="error('company_name')" :disabled="auth.loading" /><PrimaryButton :loading="auth.loading">Crear cuenta</PrimaryButton></form><p class="form-switch">¿Ya tienes cuenta? <RouterLink to="/login">Inicia sesión</RouterLink></p></AuthLayout></template>
